class Solution {
    public int kthInGrid(int[][] grid, int k) {
        int n = grid.length;
        int[] all = new int[n * n];
        for (int r = 0; r < n; r++) System.arraycopy(grid[r], 0, all, r * n, n);
        Arrays.sort(all);
        return all[k - 1];
    }
}

