static int cmpInt(const void* a, const void* b) {
    int p = *(const int*) a, q = *(const int*) b;
    return (p > q) - (p < q);
}

int kthInGrid(int** grid, int gridSize, int* gridColSize, int k) {
    int n = gridSize;
    int* all = malloc(n * n * sizeof(int));
    for (int r = 0; r < n; r++) memcpy(all + r * n, grid[r], n * sizeof(int));
    qsort(all, n * n, sizeof(int), cmpInt);
    int answer = all[k - 1];
    free(all);
    return answer;
}

