import heapq

class Solution:
    def kthInGrid(self, grid: List[List[int]], k: int) -> int:
        n = len(grid)
        heap = [(grid[r][0], r, 0) for r in range(n)]
        heapq.heapify(heap)
        for _ in range(k):
            v, r, c = heapq.heappop(heap)
            if c + 1 < n:
                heapq.heappush(heap, (grid[r][c + 1], r, c + 1))
        return v

