class Solution {
    public int kthInGrid(int[][] grid, int k) {
        int n = grid.length;
        PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
        for (int r = 0; r < n; r++) heap.add(new int[] {grid[r][0], r, 0});
        int[] top = null;
        for (int t = 0; t < k; t++) {
            top = heap.poll();
            int r = top[1], c = top[2];
            if (c + 1 < n) heap.add(new int[] {grid[r][c + 1], r, c + 1});
        }
        return top[0];
    }
}

