class Solution {
public:
    int kthInGrid(vector<vector<int>>& grid, int k) {
        int n = grid.size();
        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<>> heap;
        for (int r = 0; r < n; r++) heap.push({grid[r][0], r, 0});
        int v = 0;
        for (int t = 0; t < k; t++) {
            auto [val, r, c] = heap.top();
            heap.pop();
            v = val;
            if (c + 1 < n) heap.push({grid[r][c + 1], r, c + 1});
        }
        return v;
    }
};

