typedef struct { int v, r, c; } Item;

static void siftDown(Item* h, int size, int i) {
    while (1) {
        int l = 2 * i + 1, s = i;
        if (l < size && h[l].v < h[s].v) s = l;
        if (l + 1 < size && h[l + 1].v < h[s].v) s = l + 1;
        if (s == i) return;
        Item t = h[i]; h[i] = h[s]; h[s] = t;
        i = s;
    }
}

int kthInGrid(int** grid, int gridSize, int* gridColSize, int k) {
    int n = gridSize, size = n;
    Item* h = malloc(n * sizeof(Item));
    for (int r = 0; r < n; r++) h[r] = (Item) {grid[r][0], r, 0};
    for (int i = n / 2 - 1; i >= 0; i--) siftDown(h, size, i);
    int v = 0;
    for (int t = 0; t < k; t++) {
        Item top = h[0];
        v = top.v;
        if (top.c + 1 < n) h[0] = (Item) {grid[top.r][top.c + 1], top.r, top.c + 1};
        else h[0] = h[--size];
        siftDown(h, size, 0);
    }
    free(h);
    return v;
}

