class Solution {
    public int kthInGrid(int[][] grid, int k) {
        long lo = grid[0][0], hi = grid[grid.length - 1][grid.length - 1];
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (countAtMost(grid, mid) >= k) hi = mid;
            else lo = mid + 1;
        }
        return (int) lo;
    }

    private int countAtMost(int[][] grid, long v) {
        int n = grid.length, r = n - 1, c = 0, total = 0;
        while (r >= 0 && c < n) {
            if (grid[r][c] <= v) { total += r + 1; c++; }
            else r--;
        }
        return total;
    }
}

